<div class="card p-3"><h5>Result import and correction history</h5>
<form method="get"><input type="hidden" name="tab" value="history"><label class="form-label">Notification</label><select name="notif_id" class="form-select mb-3" onchange="this.form.submit()"><?php foreach($notifications as $n): ?><option value="<?= (int)$n['id'] ?>" <?= (int)$n['id']===(int)$reconNotifId?'selected':'' ?>><?= htmlspecialchars($n['notification_code'].' — '.$n['title']) ?></option><?php endforeach; ?></select><button class="btn btn-secondary">View history</button></form>
